using System.Text;

namespace XfsTestGen;

/// <summary>
/// Emits the native side: per struct Fill_/Free_/Verify_ helpers plus the exports the C# tests call.
/// Fill builds the expected block, Verify compares a block built by C# against it (first differing field).
/// </summary>
public static class CppWriter
{
    public const string CommonHeader = """
        // <auto-generated by XfsTestGen. Do not edit.>
        #pragma once
        #include <windows.h>
        #include <cstddef>
        #include <cstdlib>
        #include <cstring>
        #include <type_traits>

        #define EXPORT extern "C" __declspec(dllexport)

        inline bool SameStr(const char* a, const char* b) { return (a == nullptr || b == nullptr) ? a == b : strcmp(a, b) == 0; }
        inline bool SameWStr(const wchar_t* a, const wchar_t* b) { return (a == nullptr || b == nullptr) ? a == b : wcscmp(a, b) == 0; }
        inline bool SameBytes(const void* a, const void* b, size_t n) { return (a == nullptr || b == nullptr) ? a == b : memcmp(a, b, n) == 0; }

        """;

    public static string Header(string device, IEnumerable<StructModel> structs)
    {
        var sb = new StringBuilder();
        sb.AppendLine("// <auto-generated by XfsTestGen. Do not edit.>");
        sb.AppendLine("#pragma once");
        sb.AppendLine("#include \"Common.g.h\"");
        sb.AppendLine($"#include <xfs{device}.h>");
        sb.AppendLine();
        foreach (var m in structs)
        {
            var f = m.Planned.Name;
            var t = m.Planned.TypedefName;
            sb.AppendLine($"void Fill_{f}({t}& s, int sc);");
            sb.AppendLine($"void Free_{f}({t}& s);");
            sb.AppendLine($"int Verify_{f}(const {t}& e, const {t}& g);");
        }

        return sb.ToString();
    }

    public static string Source(string device, IReadOnlyList<StructModel> structs, IEnumerable<string> includeDevices)
    {
        var sb = new StringBuilder();
        sb.AppendLine("// <auto-generated by XfsTestGen. Do not edit.>");
        foreach (var d in includeDevices)
            sb.AppendLine($"#include \"{char.ToUpperInvariant(d[0])}{d[1..]}.g.h\"");
        sb.AppendLine();

        foreach (var m in structs)
        {
            var f = m.Planned.Name;
            var t = m.Planned.TypedefName;

            sb.AppendLine($"// ---- {t} ({f}) ----");
            sb.AppendLine($"void Fill_{f}({t}& s, int sc)");
            sb.AppendLine("{");
            sb.AppendLine("    memset(&s, 0, sizeof(s));");
            sb.AppendLine("    if (sc == 1) return;");
            foreach (var field in m.Fields)
                AppendFill(sb, field);
            sb.AppendLine("}");
            sb.AppendLine();

            sb.AppendLine($"void Free_{f}({t}& s)");
            sb.AppendLine("{");
            foreach (var field in m.Fields)
                AppendFree(sb, field);
            sb.AppendLine("}");
            sb.AppendLine();

            sb.AppendLine($"int Verify_{f}(const {t}& e, const {t}& g)");
            sb.AppendLine("{");
            foreach (var field in m.Fields)
                AppendVerify(sb, field);
            sb.AppendLine("    return 0;");
            sb.AppendLine("}");
            sb.AppendLine();

            sb.AppendLine($"EXPORT {t}* Native_Create_{f}(int sc) {{ auto* p = ({t}*)malloc(sizeof({t})); Fill_{f}(*p, sc); return p; }}");
            sb.AppendLine($"EXPORT void Native_Free_{f}({t}* p) {{ if (p) {{ Free_{f}(*p); free(p); }} }}");
            sb.AppendLine($"EXPORT int Native_Verify_{f}(const {t}* got, int sc) {{ {t} e; Fill_{f}(e, sc); int rc = Verify_{f}(e, *got); Free_{f}(e); return rc; }}");

            sb.AppendLine($"EXPORT int Native_Layout_{f}(const char* field)");
            sb.AppendLine("{");
            sb.AppendLine($"    if (!field) return (int)sizeof({t});");
            foreach (var field in m.Fields)
                sb.AppendLine($"    if (!strcmp(field, \"{field.CName}\")) return (int)offsetof({t}, {field.CName});");
            sb.AppendLine("    return -1;");
            sb.AppendLine("}");
            sb.AppendLine();
        }

        return sb.ToString();
    }

    private static void AppendFill(StringBuilder sb, FieldModel f)
    {
        var s = $"s.{f.CName}";
        switch (f.Kind)
        {
            case Kind.Number when !f.IsConsumedLength:
                sb.AppendLine($"    {s} = (decltype({s})){f.Index + 1};");
                break;
            case Kind.Bool:
                sb.AppendLine($"    {s} = TRUE;");
                break;
            case Kind.NumberArray:
                sb.AppendLine($"    for (int j = 0; j < {f.ArraySize}; j++) {s}[j] = (std::decay_t<decltype({s}[0])>)((({f.Index} * 7 + j) % 250) + 1);");
                break;
            case Kind.String:
                sb.AppendLine($"    {s} = _strdup(\"s{f.Index}\");");
                break;
            case Kind.WString:
                sb.AppendLine($"    {s} = _wcsdup(L\"w{f.Index}\");");
                break;
            case Kind.BytesTerminated:
                sb.AppendLine($"    {{ static const BYTE v[] = {{ 1, 2, 3, 0 }}; {s} = (decltype({s}))malloc(sizeof v); memcpy({s}, v, sizeof v); }}");
                break;
            case Kind.BytesCounted:
                sb.AppendLine($"    {{ static const BYTE v[] = {{ 1, 2, 0, 4, 0, 0, 7 }}; {s} = (decltype({s}))malloc(sizeof v); memcpy({s}, v, sizeof v); s.{f.Length!.CName} = (decltype(s.{f.Length.CName}))sizeof v; }}");
                break;
            case Kind.PrimitiveList:
            case Kind.EnumList:
            {
                var items = f.Kind == Kind.EnumList ? "1, 2, 0" : string.Join(", ", f.ListItems) + ", 0";
                sb.AppendLine($"    {{ static const std::remove_pointer_t<decltype({s})> v[] = {{ {items} }}; {s} = (decltype({s}))malloc(sizeof v); memcpy({s}, v, sizeof v); }}");
                break;
            }
            case Kind.Nested:
                sb.AppendLine($"    {s} = (decltype({s}))calloc(1, sizeof(*{s})); Fill_{f.Target}(*{s}, 0);");
                break;
            case Kind.StructList:
                sb.AppendLine($"    {s} = (decltype({s}))calloc(3, sizeof(*{s}));");
                sb.AppendLine($"    for (int j = 0; j < 2; j++) {{ {s}[j] = (std::remove_reference_t<decltype(*{s})>)calloc(1, sizeof(**{s})); Fill_{f.Target}(*{s}[j], 0); }}");
                break;
        }
    }

    private static void AppendFree(StringBuilder sb, FieldModel f)
    {
        var s = $"s.{f.CName}";
        switch (f.Kind)
        {
            case Kind.String:
            case Kind.WString:
            case Kind.BytesTerminated:
            case Kind.BytesCounted:
            case Kind.PrimitiveList:
            case Kind.EnumList:
                sb.AppendLine($"    free({s});");
                break;
            case Kind.Nested:
                sb.AppendLine($"    if ({s}) {{ Free_{f.Target}(*{s}); free({s}); }}");
                break;
            case Kind.StructList:
                sb.AppendLine($"    if ({s}) {{ for (int j = 0; {s}[j]; j++) {{ Free_{f.Target}(*{s}[j]); free({s}[j]); }} free({s}); }}");
                break;
        }
    }

    private static void AppendVerify(StringBuilder sb, FieldModel f)
    {
        var e = $"e.{f.CName}";
        var g = $"g.{f.CName}";
        var rc = f.Index + 1;
        switch (f.Kind)
        {
            case Kind.Number:
            case Kind.Bool:
                sb.AppendLine($"    if ({e} != {g}) return {rc};");
                break;
            case Kind.NumberArray:
                sb.AppendLine($"    if (memcmp({e}, {g}, sizeof {e})) return {rc};");
                break;
            case Kind.String:
                sb.AppendLine($"    if (!SameStr({e}, {g})) return {rc};");
                break;
            case Kind.WString:
                sb.AppendLine($"    if (!SameWStr({e}, {g})) return {rc};");
                break;
            case Kind.BytesTerminated:
                sb.AppendLine($"    if (!SameBytes({e}, {g}, 4)) return {rc};");
                break;
            case Kind.BytesCounted:
                sb.AppendLine($"    if (!SameBytes({e}, {g}, e.{f.Length!.CName})) return {rc};");
                break;
            case Kind.PrimitiveList:
                sb.AppendLine($"    if (!SameBytes({e}, {g}, sizeof(*{e}) * {f.ListItems.Length + 1})) return {rc};");
                break;
            case Kind.EnumList:
                sb.AppendLine($"    if (!SameBytes({e}, {g}, sizeof(*{e}) * 3)) return {rc};");
                break;
            case Kind.Nested:
                sb.AppendLine($"    if (({e} == nullptr) != ({g} == nullptr)) return {rc};");
                sb.AppendLine($"    if ({e} && Verify_{f.Target}(*{e}, *{g})) return {rc};");
                break;
            case Kind.StructList:
                sb.AppendLine($"    if (({e} == nullptr) != ({g} == nullptr)) return {rc};");
                sb.AppendLine($"    if ({e}) {{ int j = 0; for (; {e}[j]; j++) if (!{g}[j] || Verify_{f.Target}(*{e}[j], *{g}[j])) return {rc}; if ({g}[j]) return {rc}; }}");
                break;
        }
    }
}
